import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type SevenStagesProps = Record<string, any>;

const SevenStages: React.FC<SevenStagesProps> = ({
  backgroundColor = "#F5F5F5",
  primaryColor = "#E17A00",
  textColor = "#FFFFFF",
  transparentBackground = false,
  durationInSeconds = 5,
  stages = [
    "Ideation Phase",
    "Research & Data",
    "Prototype Design",
    "Development",
    "Testing & QA",
    "Final Polish",
    "Deployment"
  ],
  roundness = 16,
  fontSize = 42,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation Timing Logic
  const staggerDelay = 5; // Frames between each item start
  
  // Layout Calculations
  // Adjusted for social media safe zones (centering + side padding)
  const containerWidth = width * 0.75; // Reduced width to avoid side UI cuts
  const containerHeight = height * 0.75; // Symmetric height to center content vertically
  
  // Dynamic spacing
  const gap = containerHeight * 0.02;
  const itemHeight = (containerHeight - (gap * (stages.length - 1))) / stages.length;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          height: containerHeight,
          width: containerWidth,
          gap: gap,
        }}
      >
        {stages.map((stageText, index) => {
          // Stagger logic
          const delay = index * staggerDelay;
          
          // Spring animation for "pop up" effect
          const spr = spring({
            frame: frame - delay,
            fps,
            config: {
              damping: 12,
              stiffness: 100,
              mass: 0.8,
            },
          });

          // Interpolations
          const opacity = interpolate(spr, [0, 1], [0, 1]);
          const scale = interpolate(spr, [0, 1], [0.8, 1]);
          const translateY = interpolate(spr, [0, 1], [50, 0]);

          return (
            <div
              key={index}
              style={{
                flex: 1,
                display: "flex",
                alignItems: "center",
                backgroundColor: primaryColor,
                borderRadius: roundness,
                padding: "0 30px", // Slightly reduced horizontal padding
                opacity,
                transform: `scale(${scale}) translateY(${translateY}px)`,
                boxShadow: "0 10px 20px rgba(0,0,0,0.1)",
              }}
            >
              {/* Number Badge */}
              <div
                style={{
                  width: itemHeight * 0.5,
                  height: itemHeight * 0.5,
                  borderRadius: "50%",
                  backgroundColor: "rgba(255,255,255,0.2)",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  marginRight: 20, // Adjusted margin
                  flexShrink: 0,
                }}
              >
                <span
                  style={{
                    color: textColor,
                    fontSize: fontSize * 0.8,
                    fontWeight: 700,
                  }}
                >
                  {index + 1}
                </span>
              </div>

              {/* Text Content */}
              <span
                style={{
                  color: textColor,
                  fontSize: fontSize,
                  fontWeight: 600,
                  whiteSpace: "nowrap",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                }}
              >
                {stageText}
              </span>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default SevenStages;